// Words for every CloudIVR email, in the three app languages. Templates (email-templates.js) pick the account's language.
// Functions get the template data `d` and the formatters `f` ({ usd, date, dt, dur }).

// n + singular/plural word (French uses the singular for 0 and 1).
const pl = (n, one, many) => `${n} ${n === 1 ? one : many}`
const plFr = (n, one, many) => `${n} ${n <= 1 ? one : many}`

